/* -------- Transformer encoder block -------- */
static Value h_matrix(int rows,int cols,int fi,int fo){Value m=va();for(int r=0;r<rows;r++){Value row=va();for(int c=0;c<cols;c++)ap(row.u.a,vf(havier_rand(fi,fo)));ap(m.u.a,row);}return m;}
static Value ai_transformer(VM*vm,int n,Value*a){(void)vm;if(n<2||n>4||a[0].t!=VINT||a[1].t!=VINT)return vn();int d=(int)a[0].u.i,heads=(int)a[1].u.i,ff=n>=3&&a[2].t==VINT?(int)a[2].u.i:d*4;if(d<4||d>256||heads<1||heads>16||d%heads||ff<d||ff>1024)return vn();Value o=vsobj();stput(o.u.st,"kind",vs("transformer"));stput(o.u.st,"dim",vi(d));stput(o.u.st,"heads",vi(heads));stput(o.u.st,"ff",vi(ff));stput(o.u.st,"Wq",h_matrix(d,d,d,d));stput(o.u.st,"Wk",h_matrix(d,d,d,d));stput(o.u.st,"Wv",h_matrix(d,d,d,d));stput(o.u.st,"Wo",h_matrix(d,d,d,d));stput(o.u.st,"W1",h_matrix(ff,d,d,ff));stput(o.u.st,"W2",h_matrix(d,ff,ff,d));Value b1=va(),b2=va();for(int i=0;i<ff;i++)ap(b1.u.a,vf(0));for(int i=0;i<d;i++)ap(b2.u.a,vf(0));stput(o.u.st,"b1",b1);stput(o.u.st,"b2",b2);return o;}
static Value h_matvec(Value m,Value row){Value out=va();if(m.t!=VARR||row.t!=VARR)return out;for(size_t r=0;r<m.u.a->n;r++){Value w=m.u.a->v[r];double s=0;if(w.t!=VARR||w.u.a->n!=row.u.a->n)return va();for(size_t i=0;i<row.u.a->n;i++)s+=dn(w.u.a->v[i])*dn(row.u.a->v[i]);ap(out.u.a,vf(s));}return out;}
static Value ai_transformer_forward(VM*vm,int n,Value*a){(void)vm;if(n!=2||a[0].t!=VSTRUCT||a[1].t!=VARR)return vn();Value m=a[0],seq=a[1];Value dv=stget(m.u.st,"dim"),hv=stget(m.u.st,"heads"),ffv=stget(m.u.st,"ff");if(dv.t!=VINT||hv.t!=VINT||ffv.t!=VINT)return vn();int d=(int)dv.u.i,heads=(int)hv.u.i,ff=(int)ffv.u.i;if(seq.u.a->n>512)return vn();for(size_t i=0;i<seq.u.a->n;i++)if(seq.u.a->v[i].t!=VARR||seq.u.a->v[i].u.a->n!=(size_t)d)return vn();Value Q=va(),K=va(),V=va();for(size_t t=0;t<seq.u.a->n;t++){ap(Q.u.a,h_matvec(stget(m.u.st,"Wq"),seq.u.a->v[t]));ap(K.u.a,h_matvec(stget(m.u.st,"Wk"),seq.u.a->v[t]));ap(V.u.a,h_matvec(stget(m.u.st,"Wv"),seq.u.a->v[t]));}int hd=d/heads;Value att=va();for(size_t i=0;i<seq.u.a->n;i++){double*sc=(double*)xmalloc(seq.u.a->n*sizeof(double));if(!sc)return vn();Value row=va();for(int hidx=0;hidx<heads;hidx++){double mx=-HUGE_VAL,sum=0;for(size_t j=0;j<seq.u.a->n;j++){double z=0;for(int zidx=0;zidx<hd;zidx++){int off=hidx*hd+zidx;z+=dn(Q.u.a->v[i].u.a->v[off])*dn(K.u.a->v[j].u.a->v[off]);}sc[j]=z/sqrt((double)hd);mx=fmax(mx,sc[j]);}for(size_t j=0;j<seq.u.a->n;j++){sc[j]=exp(sc[j]-mx);sum+=sc[j];}for(int zidx=0;zidx<hd;zidx++){double z=0;for(size_t j=0;j<seq.u.a->n;j++)z+=sc[j]*dn(V.u.a->v[j].u.a->v[hidx*hd+zidx]);ap(row.u.a,vf(z/sum));}}xfree(sc);Value proj=h_matvec(stget(m.u.st,"Wo"),row);Value res=va();for(int z=0;z<d;z++)ap(res.u.a,vf(dn(seq.u.a->v[i].u.a->v[z])+dn(proj.u.a->v[z])));Value ln=nai_layernorm(vm,1,(Value[]){res});Value h1=h_matvec(stget(m.u.st,"W1"),ln);for(int z=0;z<ff;z++)h1.u.a->v[z]=vf(.5*dn(h1.u.a->v[z])*(1+tanh(sqrt(2.0/M_PI)*(dn(h1.u.a->v[z])+.044715*pow(dn(h1.u.a->v[z]),3))))+dn(stget(m.u.st,"b1").u.a->v[z]));Value h2=h_matvec(stget(m.u.st,"W2"),h1);Value fin=va();Value b2=stget(m.u.st,"b2");for(int z=0;z<d;z++)ap(fin.u.a,vf(dn(ln.u.a->v[z])+dn(h2.u.a->v[z])+dn(b2.u.a->v[z])));ap(att.u.a,fin);}return att;}

